statement: -- =========================================================
-- Locus — schéma corrigé (idempotent)
-- =========================================================

-- 1. ENUMS (CREATE TYPE ne supporte pas IF NOT EXISTS)
do $$ begin
  create type user_role as enum ('responsable','salarie');
exception when duplicate_object then null; end $$;

do $$ begin
  create type work_shift as enum ('matin','apres_midi','nuit');
exception when duplicate_object then null; end $$;

-- 2. TABLES
create table if not exists stations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  allowed_ip text,
  created_at timestamptz default now()
);

create table if not exists profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  role user_role default 'salarie',
  shift work_shift,
  points int default 0,
  station_id uuid references stations(id),
  access_code text unique,
  created_at timestamptz default now()
);
-- au cas où profiles existait déjà sans la colonne
alter table profiles add column if not exists access_code text unique;

create table if not exists attendance (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references profiles(id) on delete cascade,
  clock_in timestamptz default now(),
  clock_out timestamptz
);

create table if not exists warnings (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references profiles(id) on delete cascade,
  reason text,
  severity text default 'info',
  created_at timestamptz default now()
);

create table if not exists tasks (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  scope text default 'common',
  shift work_shift,
  station_id uuid references stations(id),
  created_at timestamptz default now()
);

create table if not exists task_completions (
  id uuid primary key default gen_random_uuid(),
  task_id uuid references tasks(id) on delete cascade,
  user_id uuid references profiles(id) on delete cascade,
  completed_at timestamptz default now(),
  unique (task_id, user_id)
);

-- 3. SÉQUENCE + RPC code d'accès
create sequence if not exists access_code_seq start 100001;

create or replace function public.next_access_code() returns text as $$
begin
  return lpad(nextval('access_code_seq')::text, 6, '0');
end;
$$ language plpgsql security definer;
grant execute on function public.next_access_code() to anon, authenticated;

-- 4. TRIGGER création de profil à l'inscription
create or replace function public.create_profile_on_signup() returns trigger as $$
begin
  insert into profiles(id, full_name, role, access_code, created_at)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name',''),
    'salarie',
    new.raw_user_meta_data->>'access_code',
    now()
  );
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.create_profile_on_signup();

-- 5. HELPER RLS
create or replace function public.is_responsable() returns boolean as $$
begin
  return exists(select 1 from profiles p where p.id = auth.uid() and p.role = 'responsable');
end;
$$ language plpgsql security definer;

-- 6. RLS + POLICIES (une seule action par policy ; insert => with check)
alter table profiles         enable row level security;
alter table stations         enable row level security;
alter table attendance       enable row level security;
alter table warnings         enable row level security;
alter table tasks            enable row level security;
alter table task_completions enable row level security;

-- profiles
drop policy if exists "profiles_self" on profiles;
create policy "profiles_select_self" on profiles for select using (id = auth.uid());
create policy "profiles_update_self" on profiles for update using (id = auth.uid());

-- stations
drop policy if exists "stations_select_auth" on stations;
drop policy if exists "stations_update_responsable" on stations;
create policy "stations_select_auth" on stations for select to authenticated using (true);
create policy "stations_update_responsable" on stations for update to authenticated using (public.is_responsable());

-- attendance
drop policy if exists "attendance_self" on attendance;
create policy "attendance_select_self" on attendance for select using (user_id = auth.uid());
create policy "attendance_insert_self" on attendance for insert with check (user_id = auth.uid());
create policy "attendance_update_self" on attendance for update using (user_id = auth.uid());

-- warnings
drop policy if exists "warnings_self" on warnings;
drop policy if exists "warnings_insert_responsable" on warnings;
create policy "warnings_select_self" on warnings for select using (user_id = auth.uid());
create policy "warnings_insert_responsable" on warnings for insert with check (public.is_responsable());

-- tasks
drop policy if exists "tasks_select_auth" on tasks;
drop policy if exists "tasks_manage_responsable" on tasks;
create policy "tasks_select_auth" on tasks for select to authenticated using (true);
create policy "tasks_manage_responsable" on tasks for all to authenticated
  using (public.is_responsable()) with check (public.is_responsable());

-- task_completions
drop policy if exists "task_completions_self" on task_completions;
create policy "tc_select_self" on task_completions for select using (user_id = auth.uid());
create policy "tc_insert_self" on task_completions for insert with check (user_id = auth.uid());
create policy "tc_delete_self" on task_completions for delete using (user_id = auth.uid());

-- 7. SEED (station + tâches)
insert into stations (name, allowed_ip)
select 'Station Test', null
where not exists (select 1 from stations where name = 'Station Test');

with s as (select id from stations where name = 'Station Test' limit 1)
insert into tasks (title, scope, shift, station_id)
select x.title, x.scope, x.shift, s.id
from s cross join (values
  ('Ouvrir caisse','common', null::work_shift),
  ('Fermer caisse','common', null::work_shift),
  ('Remplir carburant','specific','matin'::work_shift),
  ('Nettoyage pompe','specific','apres_midi'::work_shift),
  ('Vérifier stocks','specific','nuit'::work_shift)
) as x(title,scope,shift)
where not exists (select 1 from tasks t where t.title = x.title);

